  {name:'قسّم ثم ادمج',algo:'merge',arr:[6,2,5,1],order:'asc',goal:'تابع التقسيم ثم اختر العنصر التالي أثناء الدمج.'},
  {name:'اختبار الـ Pivot',algo:'quick',arr:[7,3,5,2,6],order:'asc',goal:'قارن القيم بالـ Pivot ثم ثبّت مكانه.'}
